import { PRIORITY_ORDER } from "./defaults";
import type { Settings } from "./types";

export const AGENTS_MARKER = "<!-- generated by kyle-tickets -->";
export const AGENTS_NAME = "AGENTS.md";

/** True when `existing` was generated by the plugin (so it may be regenerated). */
export function isGeneratedAgentsDoc(existing: string): boolean {
  return existing.includes(AGENTS_MARKER);
}

/** The `AGENTS.md` written into the tickets folder. Pure; uses the vault's actual prefix and statuses. */
export function renderAgentsDoc(s: Settings): string {
  const statuses = [...s.statuses].sort((a, b) => a.order - b.order);
  const P = s.prefix;
  const statusList = statuses.map((x) => `- \`${x.name}\` (${x.category})${x.name === s.defaultStatus ? " - default" : ""}`);
  const review = statuses.find((x) => x.name.toLowerCase() === "in review")?.name ?? statuses.find((x) => x.category === "started")?.name ?? "In Review";
  return `${AGENTS_MARKER}
# Working with tickets (${P}-)

This folder is a kyle-tickets issue tracker: one Markdown file per issue. Prefer the \`kh tickets\` CLI (\`kt\` is the same command and stays valid) over editing files by hand. Do not edit this file; it is regenerated when the prefix, statuses or display name change.

## Layout

\`\`\`
${s.folder}/
  Issues/${P}-1.md ...     one file per issue; the file name is the ID
  Projects/<Name>.md       projects (kind: kt-project) with milestones
  AGENTS.md                this file
  .kyle-tickets.json       marker used by kt to find this folder
\`\`\`

## Ticket file

\`\`\`md
---
id: ${P}-12
title: Fix login bug
aliases: [Fix login bug]
status: ${review}
priority: high
assignee: claude
project: "[[Website]]"
milestone: Phase 1
tags: [bug, frontend]
due: 2026-12-01
parent: "[[${P}-3]]"
related: [${P}-7]
pullRequests:
  - https://github.com/owner/repo/pull/4
created: 2026-11-21T10:04:00
updated: 2026-11-21T10:31:00
updatedBy: claude
sortOrder: 1000
---
Description in Markdown.

## Activity

- 2026-11-21 10:04 · @${s.displayName} created the issue
- 2026-11-21 10:20 · @claude set status: Todo → ${review}

### @claude · 2026-11-21 10:31
Implemented the parser; tests added.
\`\`\`

- \`status\` must be one of these exact names:
${statusList.join("\n")}
- \`priority\`: ${PRIORITY_ORDER.join(" | ")} (default none).
- \`tags\` are labels. \`parent\` and \`project\` are wiki links. \`milestone\` is a milestone name from that project.
- Times are local, \`YYYY-MM-DDTHH:mm:ss\` in frontmatter and \`YYYY-MM-DD HH:mm\` in the feed.
- Keep unknown frontmatter keys and the description as they are.

## Activity

Everything under the first \`## Activity\` heading is the feed, oldest first, new entries appended.

- Event: one line, \`- YYYY-MM-DD HH:mm · @author text\`.
- Comment: a \`### @author · YYYY-MM-DD HH:mm\` heading, then a Markdown body until the next \`###\` or the end of the file.
- Comment ids/threads: the heading may end with an HTML comment, \`### @author · YYYY-MM-DD HH:mm <!-- kt id:c1a2b3 reply:c9z8y7 edited -->\` (\`id\` stable id, \`reply\` parent id, \`edited\` flag). Headings without it are legacy comments with implicit ids \`L0\`, \`L1\`, … (by order). Use \`kt comment <ID> --reply-to <comment-id>\`; \`kt show --json\` lists comment ids.
- Escaping: in a comment body, a line that starts with \`###\` or with \`- YYYY-MM-DD HH:mm \` gets one leading backslash (\`\### text\`). The parser removes it. \`kt comment\` does this for you.

## IDs

Never guess the next ID. \`kt new\` allocates \`${P}-<n>\` (highest existing number + 1, never reusing deleted numbers) and prints it.

## kt commands (identical under \`kh tickets\`)

Run from inside the vault, or pass \`--dir <tickets folder>\` or set \`KT_DIR\`. Add \`--json\` to \`list\` and \`show\` for machine output.

\`\`\`sh
kt new "Fix login bug" --status Todo --priority high --project Website --label bug   # prints ${P}-n
kt set ${P}-12 status "${review}" --as claude          # also: priority, assignee, project, milestone, due, parent, title
kt set ${P}-12 labels +bug -frontend --as claude
kt comment ${P}-12 --as claude "Implemented; tests pass"   # "-" or no text reads stdin
kt comment ${P}-12 --as claude --reply-to c1a2b3 "Thanks"   # reply in a thread (one level)
kt list --status Todo --project Website --json
kt show ${P}-12
kt pr ${P}-12 https://github.com/owner/repo/pull/4 --as claude
kt relate ${P}-12 ${P}-7 --as claude   # related issues (shown symmetrically); kt unrelate removes
\`\`\`

Use \`none\` to clear assignee, project, milestone, due or parent. Exit codes: 0 ok, 1 usage, 2 not found, 3 validation (the message lists valid values).

## Etiquette

- Pass \`--as <agent-name>\` on every write so events and comments are attributed to you (default: \`KT_AUTHOR\`, else \`${s.displayName}\`). If you edit a file by hand, set \`updatedBy\` to your name.
- Comment with progress while you work, and when you finish.
- Move a finished ticket to \`${review}\`, never to Done or Canceled; the owner does that.
- Do not delete tickets or rename files.
`;
}
